async function loadData() {
  try {
    let response = await fetch(url);
    let data = await response.json();
    let datas = data.products;
    console.log(datas);

    // populate_html(datas);

  } catch (error) {
    console.log("Network error");
  }
}

function populate_html(datas) {
    let html = '';
    datas.forEach(data => {
        console.log(data);

        html += '<div class="category-card">';
        html += '<div class="card-title">';
        html += '<h2>' + data.abbreviated_product_name_fr + '</h2>';
        html += '</div>';
        html += '<div class="card-content">';
        html += '<img class="card-picture" src="' + data.image_url + '" alt="product image">';
        html += '</img>';
        html += '<div class="card-env-score">';
        html += '<p>Environment score : ' + data.environmental_score_tags;
        html += '</div>';
        html += '</div>';
        html += '</div>';
    });
    categories_container.innerHTML = html;
}

